(function(){
  var h=String(result||'');
  if(h.length<100)return [];
  var J=Packages.org.jsoup.Jsoup,d=J.parse(h);
  var as=d.select('a[href*=/anime/]');
  var out=[],seen={};
  for(var i=0;i<as.size();i++){
    var a=as.get(i);
    var u=String(a.attr('href')||'');
    var pic=String(a.attr('data-original')||'');
    var n=String(a.attr('title')||'').trim();
    if(!u||!pic||!n||seen[u])continue;
    seen[u]=1;
    var kind='',last='';
    var li=a.closest('li');
    if(li){var bs=li.select('span b');if(bs.size()>=2){kind=String(bs.get(0).text());last=String(bs.get(bs.size()-1).text());}}
    out.push(JSON.stringify({name:n,bookUrl:u,coverUrl:pic,kind:kind,lastChapter:last}));
  }
  // ★E 版 getElements 是 `result as List<Any>`（无 NativeArray 分支），
  //   返回 Rhino 原生数组会 ClassCastException → TocEmptyException/列表空。
  //   必须返回 Java java.util.ArrayList，两版通吃。
  var list=new Packages.java.util.ArrayList();
  for(var j=0;j<out.length;j++) list.add(out[j]);
  return list;
})()

