  var status=''; var ps=d.select('p.data');
  for(var i=0;i<ps.size();i++){var t=String(ps.get(i).text());if(t.indexOf('状态')===0){status=t.replace(/^状态[：:]\s*/,'');break;}}
  var intro=tx('.detail-content')||tx('.detail-sketch');
  var o={
    a:'OmoFun', c:pic, k:meta.replace(/^类型[：:]\s*/,'').replace(/\s*\/\s*/g,'·'),
    w:status, t:status, i:intro, n:name, tocUrl:String(baseUrl||'')
  };
  return JSON.stringify(o);
})()

