(function(){
  var h=String(result||'');
  var J=Packages.org.jsoup.Jsoup, d=J.parse(h);
  var panes=d.select('div[id^=playlist]');
  var out=[], seen={};
  // E 版 getElements 只认 Java List，末尾统一转 ArrayList
  // 只取第一条播放线路（精品），避免 4 条线路重复 800+ 集
  if(panes.size()>0){
    var as=panes.get(0).select('ul.play-list-content li.play-list-content-item a');
    for(var i=0;i<as.size();i++){
      var a=as.get(i), u=String(a.attr('href')||''), n=String(a.attr('title')||a.text()||'').trim();
      if(!u||seen[u])continue; seen[u]=1;
      if(u.indexOf('/play/')<0)continue;
      out.push(JSON.stringify({n:n||('第'+(out.length+1)+'集'),u:u}));
    }
  }
  if(out.length===0){
    // 兜底：详情页「立即播放」按钮
    var pb=d.select('a.play-btn, .play-btn a').first();
    var u2=pb?String(pb.attr('href')||''):'';
    if(u2.indexOf('/play/')>=0) out.push(JSON.stringify({n:'▶ 播放',u:u2}));
  }
  var list=new Packages.java.util.ArrayList();
  for(var j=0;j<out.length;j++) list.add(out[j]);
  return list;
})()

