@js:
(function(){
  // Legado 已把播放页 HTML 放进 result，直接用（避免重复请求触发风控）
  var page=String(result||'');
  if(page.length<3000 && (page.indexOf('系统安全验证')>=0||page.indexOf('verify_check')>=0)){
    try{ OM_pass(java,OM_line(source),'search'); page=String(java.ajax(String(baseUrl||''))); }catch(e1){ }
  }
  // player_aaaa 是含嵌套 vod_data 的内联 JSON，贪婪正则会提前截断 → 括号配平提取
  var i=page.indexOf('var player_aaaa=');
  if(i<0) return '⚠ 未找到播放数据（页面结构可能已变更，或该集已下架）';
  var st=page.indexOf('{',i), dep=0, end=-1, inStr=false, q='';
  if(st<0) return '⚠ 播放数据起始符缺失';
  for(var k=st;k<page.length;k++){
    var c=page.charAt(k);
    if(inStr){ if(c==='\\'){k++;continue;} if(c===q)inStr=false; continue; }
    if(c==='"'||c==="'"){ inStr=true; q=c; continue; }
    if(c==='{')dep++; else if(c==='}'){ dep--; if(dep===0){ end=k+1; break; } }
  }
  if(end<0) return '⚠ 播放数据括号不配平';
  var pd=null;
  try{ pd=JSON.parse(page.slice(st,end)); }catch(e2){ return '⚠ 播放数据解析失败：'+e2; }
  var rawUrl=String(pd.url||'');
  if(String(pd.encrypt)==='1'){ try{ rawUrl=unescape(rawUrl); }catch(e3){ } }
  else if(String(pd.encrypt)==='2'){ try{ rawUrl=String(java.base64Decode(rawUrl)); }catch(e4){ } }
  if(!rawUrl) return '⚠ 该集暂无播放地址';
  // 构造第三方播放器页参数（与 /static/player/mp4.js 一致）
  var dmid='';
  try{ var dm=/"dmid"\s*:\s*"?(\d+)"?/.exec(page); if(dm)dmid=dm[1]; }catch(e5){ }
  if(!dmid)dmid=String(pd.id||'');
  var pic=String(pd.vod_data&&pd.vod_data.vod_pic||'');
  var picHost=pic.indexOf('http')===0?'':'https://as.cfhls.top/';
  var line=OM_line(source);
  var qs=[
    'url='+encodeURIComponent(rawUrl),
    'dmid='+encodeURIComponent(dmid),
    'next='+encodeURIComponent(String(pd.link_next||'')),
    'name='+encodeURIComponent(String(pd.vod_data&&pd.vod_data.vod_name||'')),
    'sid='+encodeURIComponent(String(pd.sid||'1')),
    'nid='+encodeURIComponent(String(pd.nid||'1')),
    'ph='+encodeURIComponent(picHost),
    'h='+encodeURIComponent(line),
    'pic='+encodeURIComponent(pic)
  ];
  var purl=OM_PLAYER+qs.join('&');
  // 第三方播放器高峰期偶发返回极短空页（曾见 16 字节 <!DOCTYPE html>）
  // → 3 次重试，每次换 ts 破缓存；仍失败给可读提示
  var playerHtml='', mm=null;
  for(var retry=0;retry<3;retry++){
    var tryUrl=purl+(retry?'&_r='+Date.now()+'_'+retry:'');
    try{ playerHtml=String(java.ajax(tryUrl)); }catch(e6){ playerHtml=''; }
    mm=/playData\('([^']+)','([^']+)'\)/.exec(playerHtml);
    if(mm) break;
    try{ Packages.java.lang.Thread.sleep(400); }catch(eSleep){ }
  }
  if(!mm) return '⚠ 播放器解析繁忙（已重试 3 次），请稍后重试或在登录面板切换线路';
  var cipher=mm[1], ivHex=mm[2];
  try{
    var keyBytes=java.strToBytes(OM_AESKEY);
    var ivBytes=java.hexDecodeToByteArray(ivHex);
    var c=java.createSymmetricCrypto('AES/CBC/PKCS7Padding',keyBytes,ivBytes);
    var u=String(c.decryptStr(cipher)).trim();
    // 站方偶发把协议头写成 org.h:// 之类的伪装，统一还原
    if(u.indexOf('org.h://')===0) u='https://'+u.slice(8);
    if(u.indexOf('http')!==0) return '⚠ 解析出的地址异常：'+u.slice(0,120);
    return u;
  }catch(e7){ return '⚠ 播放地址解密失败：'+e7; }
})()
